const b = $input.first().json.body;
const t = b.terms || {};
const total = Number(t.total_cost || 0);
return [{ json: {
  ticket: 'REV-' + String(b.plan_id || 'x').slice(-6).toUpperCase() + '-' + (b.attempt || 1),
  priority: total > 1500000 ? 'HIGH' : total > 800000 ? 'MEDIUM' : 'LOW',
  total_cost: total
} }];

const b = $('Webhook').first().json.body;
const tk = $('Open review ticket').first().json;
const r = $input.first().json || {};
const decided = r.decision === 'approve' || r.decision === 'reject';
return [{ json: decided
  ? { ok: true, workflow: 'trigger-budget-review', executionId: String($execution.id), plan_id: b.plan_id, attempt: b.attempt,
      ticket: tk.ticket, priority: tk.priority, decision: r.decision, reason: r.reason, policy_rule_applied: r.policy_rule_applied }
  : { ok: false, workflow: 'trigger-budget-review', executionId: String($execution.id), plan_id: b.plan_id, attempt: b.attempt,
      ticket: tk.ticket, error: 'policy service did not answer' } }];
